import React, { useState, useEffect, useCallback } from "react";

export default function ManageApplications() {
  const API = process.env.REACT_APP_API_BASE_URL;

  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [reviewComment, setReviewComment] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");
  const [loadingDocuments, setLoadingDocuments] = useState({});

  // ---------------- FETCH APPLICATIONS ----------------
  const fetchApplicationsForReview = useCallback(async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API}/applications/applications`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await response.json();

      if (response.ok) {
        setApplications(data.data || []);
      } else {
        setError(data.message || "Failed to fetch applications");
      }
    } catch (err) {
      setError("Network error. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [API]);

  useEffect(() => {
    fetchApplicationsForReview();
  }, [fetchApplicationsForReview]);

  // ---------------- UPDATE STATUS ----------------
  const updateApplicationStatus = async (applicationId, status) => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API}/applications/verify/${applicationId}`,
        {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ status }),
        }
      );

      const data = await response.json();

      if (response.ok) {
        setApplications((prev) =>
          prev.map((app) =>
            app.application_id === applicationId
              ? { ...app, status }
              : app
          )
        );

        setSelectedApplication(null);
        setReviewComment("");
        alert("Status updated successfully");
      } else {
        alert(data.message || "Failed to update application");
      }
    } catch (err) {
      alert("Network error. Please try again.");
    }
  };

  // ---------------- FILTER ----------------
  const getFilteredApplications = () => {
    if (filterStatus === "all") return applications;
    return applications.filter(
      (app) => app.status === filterStatus
    );
  };

  // ---------------- VIEW DOCUMENT ----------------
  const viewDocument = async (filePath, key) => {
    if (!filePath) {
      alert("Document not available");
      return;
    }

    try {
      setLoadingDocuments((prev) => ({
        ...prev,
        [key]: true,
      }));

      const backendBase =
        process.env.REACT_APP_BACKEND_URL || "http://localhost:5001";

      window.open(`${backendBase}/${filePath}`, "_blank");
    } finally {
      setLoadingDocuments((prev) => ({
        ...prev,
        [key]: false,
      }));
    }
  };

  if (loading) {
    return (
      <div className="container mt-4" style={{ paddingTop: "80px" }}>
        <div className="text-center">
          <div className="spinner-border text-primary" />
          <p className="mt-2">Loading applications...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="container-fluid mt-4" style={{ paddingTop: "120px" }}>
      <div className="card shadow">
        <div className="card-header bg-warning">
          <div className="d-flex justify-content-between">
            <div>
              <h3 className="mb-0">Review Panel</h3>
              <p className="mb-0">
                Applications: {applications.length}
              </p>
            </div>

            <select
              className="form-select"
              style={{ width: "220px" }}
              value={filterStatus}
              onChange={(e) =>
                setFilterStatus(e.target.value)
              }
            >
              <option value="all">All</option>
              <option value="Pending">Pending</option>
              <option value="Approved by Authority">
                Approved by Authority
              </option>
              <option value="Rejected by Authority">
                Rejected by Authority
              </option>
              <option value="Approved by Admin">
                Approved by Admin
              </option>
              <option value="Rejected by Admin">
                Rejected by Admin
              </option>
            </select>
          </div>
        </div>

        <div className="card-body p-0">
          {error && (
            <div className="alert alert-danger m-3">
              {error}
            </div>
          )}

          <div className="table-responsive">
            <table className="table table-hover mb-0">
              <thead className="table-light">
                <tr>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Roll</th>
                  <th>CGPA</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>

              <tbody>
                {getFilteredApplications().map((app) => (
                  <tr key={app.application_id}>
                    <td>#{app.application_id}</td>
                    <td>{app.student_name}</td>
                    <td>{app.roll}</td>
                    <td>{app.cgpa}</td>
                    <td>{getStatusBadge(app.status)}</td>
                    <td>
                      {/* AUTHORITY ACTIONS */}
                      {app.status === "Pending" && (
                        <>
                          <button
                            className="btn btn-success btn-sm me-1"
                            onClick={() =>
                              updateApplicationStatus(
                                app.application_id,
                                "Approved by Authority"
                              )
                            }
                          >
                            Approve (Authority)
                          </button>

                          <button
                            className="btn btn-danger btn-sm"
                            onClick={() =>
                              updateApplicationStatus(
                                app.application_id,
                                "Rejected by Authority"
                              )
                            }
                          >
                            Reject (Authority)
                          </button>
                        </>
                      )}

                      {/* ADMIN ACTIONS */}
                      {app.status ===
                        "Approved by Authority" && (
                        <>
                          <button
                            className="btn btn-success btn-sm me-1"
                            onClick={() =>
                              updateApplicationStatus(
                                app.application_id,
                                "Approved by Admin"
                              )
                            }
                          >
                            Approve (Admin)
                          </button>

                          <button
                            className="btn btn-danger btn-sm"
                            onClick={() =>
                              updateApplicationStatus(
                                app.application_id,
                                "Rejected by Admin"
                              )
                            }
                          >
                            Reject (Admin)
                          </button>
                        </>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

// ---------------- STATUS BADGE ----------------
const getStatusBadge = (status) => {
  const colors = {
    Pending: "bg-warning text-dark",
    "Approved by Authority": "bg-info text-white",
    "Rejected by Authority": "bg-danger text-white",
    "Approved by Admin": "bg-success text-white",
    "Rejected by Admin": "bg-dark text-white",
  };

  return (
    <span className={`badge ${colors[status] || "bg-secondary"}`}>
      {status}
    </span>
  );
};
